def bhattacharyya_coefficient(p, q):
    return float(np.sum(np.sqrt(p * q)))

def hellinger_distance_sq(p, q):
    return 1.0 - bhattacharyya_coefficient(p, q)

def sqrt_embedding(p):
    return np.sqrt(p)

def verify_on_sphere(p):
    sp = sqrt_embedding(p)
    return np.isclose(np.sum(sp**2), 1.0)

def polarization_index(voters):
    m = len(voters)
    if m <= 1: return 0.0
    total = sum(hellinger_distance_sq(voters[i], voters[j])
                for i in range(m) for j in range(m) if i != j)
    return total / (m * (m - 1))

def contraction_ratio(theta1, theta2):
    avg_cos = (np.cos(theta1) + np.cos(theta2)) / 2
    mid_cos = np.cos((theta1 + theta2) / 2)
    return mid_cos / avg_cos if abs(avg_cos) > 1e-12 else float('inf')
